params AS (
  SELECT 'So11111111111111111111111111111111111111112' AS wsol,
         DATE '2026-08-16' AS day_lo, DATE '2026-08-19' AS day_hi
)
SELECT
  pr.pool,
  pr.mint,
  pr.slot_from,
  pr.slot_to,
  t.block_slot,
  t.tx_index,
  t.outer_instruction_index,
  COALESCE(t.inner_instruction_index, -1)                       AS inner_instruction_index,
  CASE WHEN t.token_bought_mint_address = p.wsol THEN 'SELL' ELSE 'BUY' END AS side,
  -- Raw units, matching the units of the stored reserves. For a BUY the trader pays
  -- WSOL (token_sold) and receives base (token_bought); for a SELL it is reversed.
  CAST(CASE WHEN t.token_bought_mint_address = p.wsol
            THEN t.token_sold_amount_raw ELSE t.token_bought_amount_raw END AS VARCHAR) AS base_raw,
  CAST(CASE WHEN t.token_bought_mint_address = p.wsol
            THEN t.token_bought_amount_raw ELSE t.token_sold_amount_raw END AS VARCHAR) AS quote_raw
FROM pairs pr
CROSS JOIN params p
JOIN dex_solana.trades t
  ON (t.token_bought_mint_address = pr.mint OR t.token_sold_mint_address = pr.mint)
 AND t.block_slot > pr.slot_from
 AND t.block_slot <= pr.slot_to
WHERE t.project = 'pumpswap'
  AND t.block_date >= p.day_lo
  AND t.block_date <= p.day_hi
  AND (t.token_bought_mint_address = p.wsol OR t.token_sold_mint_address = p.wsol)
ORDER BY 1, 3, 5, 6, 7, 8
